param([switch]$Uninstall, [string]$GarrysModPath = "")
$ErrorActionPreference = "Stop"
try { $a1 = Split-Path -Parent $PSScriptRoot; $a2 = New-Object System.Text.UTF8Encoding($false); if ($GarrysModPath -eq "") { $GarrysModPath = Join-Path $a1 "..\.." }; if (-not (Test-Path $GarrysModPath)) { throw "Garry's Mod folder not found: $GarrysModPath" }; $a3 = (Resolve-Path $GarrysModPath).Path; $a4 = Join-Path $a3 "lua\menu\menu.lua"; if (-not (Test-Path $a4)) { throw "Could not find $a4. Make sure Lunar Shade is in garrysmod\addons\LunarShade, or run the .ps1 with -GarrysModPath 'C:\path\to\garrysmod'." }; if ($a3 -eq $a1) { throw "Run this from the addons\LunarShade folder." }; $a5 = '--[[ LUNAR SHADE MAIN MENU BEGIN (remove with Uninstall-MainMenu) ]]'; $a6 = '--[[ LUNAR SHADE MAIN MENU END ]]'; $a7 = 'MsgC(Color(157,125,255), "[Lunar Shade] menu.lua line is running\n"); pcall(file.Delete, "lunar_shade_menu_status.txt"); pcall(file.Write, "lunar_shade_probe.txt", "menu.lua line ran"); local ok, e = pcall(include, "lunar_shade_menu/mn_boot.lua"); if not file.Exists("lunar_shade_menu_status.txt", "DATA") then pcall(file.Write, "lunar_shade_menu_status.txt", "error: boot file did not run (pcall=" .. tostring(ok) .. " " .. tostring(e) .. ")") end'; $a8 = '(?s)--\[\[ LUNAR SHADE MAIN MENU BEGIN.*?LUNAR SHADE MAIN MENU END \]\]\r?\n?'; $a9 = [System.IO.File]::ReadAllText($a4); $a10 = [regex]::Replace($a9, $a8, ""); if ($Uninstall) { [System.IO.File]::WriteAllText($a4, $a10, $a2); $b1 = Join-Path $a3 "lua\lunar_shade_menu"; if (Test-Path $b1) { Remove-Item $b1 -Recurse -Force }; $b2 = Join-Path $a3 "lua\lunar_shade\sh_presets.lua"; if (Test-Path $b2) { Remove-Item $b2 -Force }; $b3 = Join-Path $a3 "lua\lunar_shade\sh_crypt.lua"; if (Test-Path $b3) { Remove-Item $b3 -Force }; $b4 = Join-Path $a3 "data\lunar_shade_menu_status.txt"; if (Test-Path $b4) { Remove-Item $b4 -Force }; Write-Host "Lunar Shade main menu removed. Restart Garry's Mod." -ForegroundColor Green }
	else { $c1 = "$a4.lunarshade.bak"; if (-not (Test-Path $c1)) { Copy-Item $a4 $c1 }; $c2 = $a5 + "`n" + $a7 + "`n" + $a6 + "`n"; [System.IO.File]::WriteAllText($a4, $c2 + $a10, $a2); $c3 = Join-Path $a3 "lua\lunar_shade_menu"; $c4 = Join-Path $a3 "lua\lunar_shade"; New-Item -ItemType Directory -Force -Path $c3 | Out-Null; New-Item -ItemType Directory -Force -Path $c4 | Out-Null; Get-ChildItem -LiteralPath (Join-Path $a1 "lua\lunar_shade_menu") -Filter "*.lua" | Copy-Item -Destination $c3 -Force; Copy-Item (Join-Path $a1 "lua\lunar_shade\sh_presets.lua") $c4 -Force; Copy-Item (Join-Path $a1 "lua\lunar_shade\sh_crypt.lua") $c4 -Force; Write-Host "Lunar Shade main menu installed." -ForegroundColor Green; Write-Host "  patched : $a4  (backup: menu.lua.lunarshade.bak)"; Write-Host "  copied  : $c3 and lua\lunar_shade\sh_presets.lua"; Write-Host "Restart Garry's Mod completely. Re-run this after updating Lunar Shade or after a Garry's Mod update." }
}
catch { Write-Host ""; Write-Host "Installation failed: $($_.Exception.Message)" -ForegroundColor Red; Write-Host "If this is a permissions error, right-click Install-MainMenu.bat and choose 'Run as administrator'."; exit 1 }
